// seedHealth stores 60 stable days before testNow (3 May 2026) and the
// given values for 2 and 3 May.
func seedHealth(t *testing.T, env *testEnv, recent store.HealthValues) {
	t.Helper()
	ctx := context.Background()
	for i := 1; i <= 60; i++ {
		off := 1
		if i%2 == 0 {
			off = -1
		}
		date := testNow.AddDate(0, 0, -i).Format(time.DateOnly)
		if err := env.store.UpsertHealth(ctx, date, store.HealthValues{"resting_hr": 50 + off, "sleep_s": 27000 + 900*off,
			"sleep_score": 80 + 4*off, "body_battery_high": 90 + 3*off, "stress_avg": 30 + 2*off}); err != nil {
			t.Fatal(err)
		}
	}
	for _, d := range []string{"2026-05-02", "2026-05-03"} {
		if err := env.store.UpsertHealth(ctx, d, recent); err != nil {
			t.Fatal(err)
		}
	}
}

