func TestInsightSettings(t *testing.T) {
	env := newTestEnv(t)
	page := env.do(ingressGET("/settings")).Body.String()
	if !strings.Contains(page, `name="ready_at" value="66"`) || !strings.Contains(page, `name="weight_load" value="0.3"`) ||
		strings.Contains(page, "Eigene Werte aktiv") {
		t.Fatal("defaults expected")
	}
	form := url.Values{}
	for k, v := range map[string]string{"window_days": "30", "weight_hrv": "0.3", "weight_rhr": "0.25", "weight_sleep": "0.25",
		"weight_body": "0.2", "weight_load": "0.3", "ready_at": "70", "limited_below": "40", "warn_rhr": "6", "warn_days": "3",
		"form_hard": "-10", "form_rest": "-20", "form_easy": "-30", "ratio_easy": "1.3", "ratio_rest": "1.5"} {
		form.Set(k, v)
	}
	if w := env.do(httptestRequest("/settings/insight", form)); w.Code != http.StatusNoContent {
		t.Fatalf("save: %d %s", w.Code, w.Body.String())
	}
	cfg := (&server{Deps: Deps{Store: env.store}}).insightSettings(context.Background())
	if cfg.WindowDays != 30 || cfg.ReadyAt != 70 || cfg.WarnRHR != 6 {
		t.Errorf("saved %+v", cfg)
	}
	if page := env.do(ingressGET("/settings")).Body.String(); !strings.Contains(page, "Eigene Werte aktiv") {
		t.Error("custom marker")
	}
	form.Set("ready_at", "30") // below "limited"
	if w := env.do(httptestRequest("/settings/insight", form)); w.Code != http.StatusUnprocessableEntity || !strings.Contains(w.Body.String(), "passen nicht zusammen") {
		t.Errorf("invalid: %d", w.Code)
	}
	form.Set("ready_at", "abc")
	if w := env.do(httptestRequest("/settings/insight", form)); w.Code != http.StatusUnprocessableEntity {
		t.Errorf("not a number: %d", w.Code)
	}
	if w := env.do(httptestRequest("/settings/insight/reset", url.Values{})); w.Code != http.StatusNoContent {
		t.Fatalf("reset: %d", w.Code)
	}
	if cfg := (&server{Deps: Deps{Store: env.store}}).insightSettings(context.Background()); cfg.WindowDays != 60 {
		t.Errorf("after reset %+v", cfg)
	}
}
